from pathlib import Path
root=Path(__file__).resolve().parents[2]
style=(root/'archive/tmp/sync-baseline/prototype-smart-acquisition.html').read_text(encoding='utf-8').split('<style>')[1].split('</style>')[0]
# Reuse the existing prototype palette without retaining obsolete pages and handlers.
html=r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>智能获客 · v3.0 需求同步原型</title><style>
:root{--bg:#080f1e;--panel:#111c30;--line:#25334b;--text:#e4ebf6;--muted:#9eafca;--accent:#6c9eff;--amber:#efc578;--good:#6cd6bb;--bad:#ff9494}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.65 'Microsoft YaHei','PingFang SC',sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;background:#243654;border:1px solid #3a5278;border-radius:6px;padding:8px 15px;color:var(--text)}button:hover{border-color:var(--accent)}button.primary{background:#3e6ebc;border-color:#5c89cf}button:disabled{opacity:.45;cursor:not-allowed}button.small{padding:4px 9px;font-size:12px}input,select,textarea{background:#0a1426;border:1px solid #354665;border-radius:5px;color:var(--text);padding:9px;width:100%}input[type=checkbox],input[type=radio]{width:auto}textarea{min-height:105px;resize:vertical}label{display:block;color:var(--muted);font-size:13px}label input,label select,label textarea{display:block;margin-top:6px}a{color:var(--accent)}h1{font-size:27px;font-weight:600;margin:0 0 10px}h2{font-size:19px;margin:0 0 15px}h3{font-size:15px;margin:0 0 10px}p{margin:7px 0 14px}.app{display:grid;grid-template-columns:215px 1fr;min-height:100vh}.sidebar{padding:28px 18px;border-right:1px solid var(--line);background:#0b1527;position:sticky;top:0;height:100vh}.brand{font-size:20px;font-weight:700;letter-spacing:1px}.version{font-size:12px;color:var(--muted);margin-bottom:25px}.nav{margin:7px 0;width:100%;text-align:left;background:none;border-color:transparent;padding:11px 14px}.nav.active{background:#1d3152;color:#a9c8ff;border-color:#385780}.sidefoot{position:absolute;bottom:25px;left:20px;right:20px;color:var(--muted);font-size:12px}.main{padding:0 38px 45px;max-width:1600px;width:100%;margin:auto}.topbar{display:flex;align-items:center;justify-content:space-between;padding:20px 0;border-bottom:1px solid var(--line);gap:16px;margin-bottom:30px}.topbar select{width:170px}.mock{border:1px solid #6f5939;background:#30291e;color:var(--amber);padding:7px 12px;border-radius:5px;font-size:12px}.muted{color:var(--muted)}.hint{font-size:12px;color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.between{justify-content:space-between}.flow{display:flex;border:1px solid var(--line);border-radius:6px;margin:24px 0;overflow:hidden}.flow span{padding:11px 18px;color:var(--muted);border-right:1px solid var(--line);flex:1}.flow .now{color:var(--amber);background:#29251e}.balance{font:26px/1.4 Consolas,monospace;color:var(--good)}.notice{border-left:3px solid var(--amber);background:#29261f;padding:12px 15px;margin:16px 0;color:#e3c99d}.tag{display:inline-block;font-size:12px;border:1px solid #425779;border-radius:4px;padding:2px 7px;color:#afc8ee}.tag.warn{color:var(--amber);border-color:#71603d}.tag.good{color:var(--good);border-color:#3f6c65}table{border-collapse:collapse;width:100%;font-size:13px}th{color:var(--muted);font-weight:400;text-align:left;background:#0d182b}td,th{padding:13px 11px;border-bottom:1px solid var(--line);vertical-align:top}.tablewrap{overflow:auto}td:last-child{white-space:nowrap}.tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin:20px 0}.tabs button{border:none;background:none;border-radius:0}.tabs button.active{color:#a9c8ff;border-bottom:2px solid var(--accent)}.item{border-bottom:1px solid var(--line);padding:17px 0}.item:last-child{border:0}.itemhead{display:flex;justify-content:space-between;gap:15px}.timeline{border-left:2px solid #3d5275;padding-left:20px;margin:20px 6px}.timeline .item{position:relative}.timeline .item:before{content:'';position:absolute;left:-26px;top:25px;width:10px;height:10px;border-radius:50%;background:var(--accent)}.dialog{position:fixed;inset:0;background:#020712bd;display:none;align-items:center;justify-content:center;padding:24px;z-index:5}.dialog.open{display:flex}.modal{background:#111c30;border:1px solid #3b506f;border-radius:10px;width:min(850px,100%);max-height:91vh;overflow:auto;padding:25px}.modal.wide{width:min(1100px,100%)}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.error{color:var(--bad);white-space:pre-wrap}.success{color:var(--good)}pre{overflow:auto;background:#081223;padding:14px;font:12px/1.65 Consolas,monospace;white-space:pre-wrap;word-break:break-word}.preview{background:#f3f6fa;color:#26364d;border-radius:5px;padding:17px;margin:12px 0}.empty{padding:28px;text-align:center;color:var(--muted)}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:#27415f;padding:12px 20px;z-index:12;border-radius:7px;display:none;max-width:80%}:focus-visible{outline:2px solid var(--amber);outline-offset:3px}details{margin:15px 0}summary{cursor:pointer;color:var(--muted)}.sr{position:absolute;width:1px;height:1px;overflow:hidden}@media(max-width:850px){.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto;border-right:0;padding:16px}.sidebar nav{display:flex;overflow:auto}.nav{white-space:nowrap;width:auto}.sidefoot{display:none}.main{padding:0 18px 30px}.grid,.grid.three{grid-template-columns:1fr}.topbar{flex-wrap:wrap}.flow span{padding:8px;font-size:11px}.modal{padding:18px}.dialog{padding:12px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><div class="app"><aside class="sidebar"><div class="brand">智能获客</div><div class="version">需求同步原型 · v3.0</div><nav id="nav"></nav><div class="sidefoot">同企业共享档案<br>腾道来源数据禁止导出<br>通知仅在系统内展示</div></aside><main class="main"><div class="topbar"><span class="mock">演示数据与费用均为模拟 · 不连接供应商</span><div class="row"><span class="hint" id="demoDate"></span><select id="role" aria-label="切换演示角色" onchange="changeRole(this.value)"><option value="admin">终端企业管理员</option><option value="sales">终端业务员</option><option value="distributor">分销管理员</option><option value="platform">平台运营</option></select></div></div><div id="view"></div></main></div><div id="dialog" class="dialog" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div id="modal" class="modal"></div></div><div id="toast" role="status"></div>
<script>
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menus={admin:['找企业','企业档案库','邮件发送记录','团队发信设置','成员管理','点数用量'],sales:['找企业','企业档案库','邮件发送记录','点数用量'],distributor:['下级管理','点数订单','交易与利润'],platform:['下级管理','点数订单','交易与利润','平台配置','业务数据查看']};
const S={role:'admin',page:'找企业',date:'2026-10-26',balance:100,frozen:0,ledger:[],requests:[],candidates:[],selectedIdentity:null,query:null,archiveTab:'概况',selected:{},ownership:{},conflicts:{},batches:[],quota:{},dailyLimit:5,defaultChannel:'smtp',priceConfigured:true,coefficient:1,querySerial:0,recordSerial:0,memberSerial:1,members:[{id:1,name:'王敏',login:'wang@example.test',role:'业务员',active:true}],channels:{smtp:{sender:'team@example.test',reply:'reply@example.test',ready:true},umail:{sender:'sales@send.example.test',reply:'reply@example.test',ready:true}},archives:[{id:'local-company-101',sourceId:'detail-901',listId:'list-501',name:'Atlas Outdoor LLC',country:'USA',status:'线索',deleted:false,products:'户外家具',needs:'待补充',intent:'待沟通',follow:'2026-10-29',fetched:'2026-10-25 10:00',records:[],attachments:[]}],companyId:'local-company-101',supplier:{balance:1000,salesReserved:0,buyerBalance:20,averageCost:.15,m:.1,order:null}};
const contacts=[{mailsouId:'ms-701',id:null,fileId:'file-not-contact-301',name:'Alex Lee',company:'Atlas Outdoor LLC',email:'buyer@atlas.example.test',personal:'alex@personal.example.test',confidence:'高度匹配'},{mailsouId:'ms-702',id:null,fileId:'file-not-contact-302',name:'Morgan Chen',company:'Atlas Outdoor LLC',email:'buyer@atlas.example.test',personal:'',confidence:'可能匹配'},{mailsouId:'ms-703',id:null,fileId:'file-not-contact-303',name:'Sam Rivera',company:'Atlas Partners Ltd',email:'sam@partners.example.test',personal:'',confidence:'匹配度低'},{mailsouId:'ms-704',id:null,fileId:'file-not-contact-304',name:'Taylor Park',company:'Atlas Outdoor LLC',email:'',personal:'taylor@personal.example.test',confidence:'系统推测'},{mailsouId:'ms-705',id:null,fileId:'file-not-contact-305',name:'Robin Wu',company:'Atlas Outdoor LLC',email:'robin@atlas.example.test',personal:'',confidence:'可能匹配',unsub:true}];
const TEMPLATES=Object.freeze({intro:Object.freeze({name:'产品介绍',subject:'Hello {{name}}',body:'Hello {{name}},\nWe would like to learn more about {{company}} and your sourcing needs.',attachments:['产品介绍.pdf（模拟预设）']}),follow:Object.freeze({name:'沟通致意',subject:'A note for {{company}}',body:'Hello {{name}},\nThank you for considering our products.',attachments:[]})});
let draft=null,priorFocus=null;
function company(){return S.archives.find(c=>c.id===S.companyId)}
function quota(date=S.date){return S.quota[date]||(S.quota[date]={used:0,reserved:0})}
function amount(n){return Number(n).toFixed(4)}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000)}
function openModal(title,body,wide=false){priorFocus=document.activeElement;$('modal').className='modal'+(wide?' wide':'');$('modal').innerHTML='<div class="row between"><h2 id="modalTitle">'+esc(title)+'</h2><button class="small" aria-label="关闭弹窗" onclick="closeModal()">关闭</button></div>'+body;$('dialog').classList.add('open');$('modal').querySelector('button,input,select,textarea')?.focus()}
function closeModal(){$('dialog').classList.remove('open');priorFocus?.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('dialog').classList.contains('open')){const nodes=[...$('modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function changeRole(role){S.role=role;closeModal();S.page=menus[role][0];render()}
function go(page){if(!menus[S.role].includes(page))return toast('当前角色无此入口');S.page=page;render()}
function render(){$('nav').innerHTML=menus[S.role].map(p=>'<button class="nav '+(p===S.page?'active':'')+'" onclick="go(\''+p+'\')">'+p+'</button>').join('');$('demoDate').textContent='北京时间 '+S.date;const views={'找企业':findView,'企业档案库':archiveView,'邮件发送记录':mailView,'团队发信设置':settingsView,'成员管理':membersView,'点数用量':pointsView,'下级管理':childrenView,'点数订单':ordersView,'交易与利润':profitsView,'平台配置':platformView,'业务数据查看':businessView};views[S.page]();}
function head(title,text){return '<h1>'+title+'</h1><p class="muted">'+text+'</p>'}
function findView(){$('view').innerHTML=head('从一个产品，找到采购企业','产品词发现历史贸易候选，或使用公司名收窄企业。候选身份由你核对。')+'<div class="flow"><span class="now">搜索候选</span><span>核对身份 / 建档</span><span>档案内找联系人</span><span>预览并发送</span></div><section class="panel"><div class="row between"><h2>找企业</h2><div>可用点数 <b class="balance">'+amount(S.balance-S.frozen)+'</b></div></div><div class="grid"><label>搜索方式<select id="searchMode" onchange="modeChanged()"><option value="product">按产品词</option><option value="company">按公司名（列表免费）</option></select></label><label>采购企业所在国家<select id="country"><option value="">请选择</option><option value="USA">美国 · USA</option><option value="DEU">德国 · DEU</option><option value="IND">印度 · IND</option></select></label><label><span id="keywordLabel">产品词</span><input id="keyword" placeholder="例如 outdoor furniture"></label><div id="dates" class="grid"><label>贸易开始日期<input type="date" id="start" value="2026-01-01"></label><label>贸易结束日期<input type="date" id="end" value="2026-10-26"></label></div></div><div class="notice" id="searchHint">产品词名单、企业详情和联系人分步确认费用。采购企业所在国家与商品目的国不直接等价；接口映射尚待验证。</div><button class="primary" onclick="searchCompanies()">查询候选</button></section><div id="candidates">'+candidateTable()+'</div>'+testTools();}
function modeChanged(){const product=$('searchMode').value==='product';$('dates').style.display=product?'grid':'none';$('keywordLabel').textContent=product?'产品词':'公司名';$('searchHint').textContent=product?'产品词需国家与贸易时间，按页确认费用；国家映射待联调，不将商品目的国当采购企业所在国。':'公司名列表查询免费；选择候选后，详情建档仍需单独费用确认。';}
function searchCompanies(){const mode=$('searchMode').value,country=$('country').value,keyword=$('keyword').value.trim(),start=$('start').value,end=$('end').value;if(!keyword||!country)return toast('请填写关键词并选择采购企业所在国家');if(mode==='product'&&(!start||!end||start>end))return toast('请填写有效贸易时间范围');if(mode==='product'&&(new Date(end)-new Date(start)>1096*86400000))return toast('演示按进口方向校验不超过3年；真实端点限制须联调');const snapshot={mode,country,keyword,start:mode==='product'?start:null,end:mode==='product'?end:null,pageNo:1,pageSize:10};if(mode==='company'){S.requests.push({kind:'free-company-list',params:{name:keyword,countryCodes:country,pageNo:1,pageSize:20}});makeCandidates(snapshot);return}requestQuery('产品词候选名单',snapshot,()=>makeCandidates(snapshot));}
function makeCandidates(snapshot){S.searchSnapshot=snapshot;S.candidates=[{key:'candidate-A',name:'Atlas Outdoor LLC'},{key:'candidate-B',name:'Atlas Partners Ltd'}];if(S.page==='找企业')$('candidates').innerHTML=candidateTable();}
function candidateTable(){return S.candidates.length?'<section class="panel"><h2>候选名单 <span class="tag warn">模拟结果 · 尚非已核实档案</span></h2><p class="hint">只处理你选择的企业，不自动建档整页；有贸易记录不代表当前采购意向。名单成功费用与后续查询分别结算。</p><table><thead><tr><th>来源名称</th><th>企业身份</th><th>操作</th></tr></thead><tbody>'+S.candidates.map((c,i)=>'<tr><td>'+esc(c.name)+'</td><td>待核实</td><td><button onclick="identify('+i+')">核对身份并建档</button></td></tr>').join('')+'</tbody></table><button class="small" style="margin-top:14px" onclick="nextCandidates()">下一页（重新确认费用）</button></section>':'';}
function nextCandidates(){const s={...S.searchSnapshot,pageNo:S.searchSnapshot.pageNo+1};if(s.mode==='company'){S.requests.push({kind:'free-company-list',params:{name:s.keyword,countryCodes:s.country,pageNo:s.pageNo,pageSize:20}});makeCandidates(s)}else requestQuery('产品词候选名单下一页',s,()=>makeCandidates(s));}
function identify(i){const c=S.candidates[i];S.identifying=c;const country=S.searchSnapshot.country;openModal('核对企业身份','<p>贸易候选名称：<b>'+esc(c.name)+'</b>。以下为模拟企业列表，必须明确选择，国家不一致不能建档。</p><label>企业身份<select id="identity"><option value="">请选择，系统不自动取第一条</option><option value="correct">'+esc(c.name)+' · '+esc(country)+' · 模拟列表ID list-502</option><option value="wrong">'+esc(c.name)+' · GBR · 模拟列表ID list-999</option></select></label><div id="identityError" class="error"></div><div class="actions"><button onclick="closeModal()">保留待核实</button><button class="primary" onclick="confirmIdentity()">确认身份，查看详情费用</button></div>');}
function confirmIdentity(){const choice=$('identity').value;if(!choice)return $('identityError').textContent='请选择企业身份';const country=choice==='wrong'?'GBR':S.searchSnapshot.country;if(country!==S.searchSnapshot.country)return $('identityError').textContent='返回企业国家与采购企业所在国家不一致，不能继续。请保留待核实。';const identity={listId:'list-502',name:S.identifying.name,country};S.selectedIdentity=Object.freeze({...identity});closeModal();requestQuery('企业详情建档',{name:identity.name,countryCode3:identity.country,selectedListId:identity.listId,pageNo:1,pageSize:1},()=>{let c=S.archives.find(x=>x.name===identity.name&&x.country===identity.country);if(!c){c={id:'local-company-'+(S.archives.length+101),sourceId:'detail-'+(S.archives.length+901),listId:identity.listId,name:identity.name,country:identity.country,status:'线索',products:'',needs:'',intent:'',follow:'',records:[],attachments:[],fetched:S.date,deleted:false};S.archives.push(c)}S.companyId=c.id;S.archiveTab='概况';S.page='企业档案库';render();toast('模拟详情可查看，已建档；仅结算本次详情查询');});}
function requestQuery(title,snapshot,onSuccess){if(!S.priceConfigured)return toast('该计费接口尚未配置单价，不能开放查询');S.query={id:'q-'+(++S.querySerial),title,snapshot:Object.freeze({...snapshot}),onSuccess,max:10,coefficient:S.coefficient};openModal(title+' · 费用确认','<div class="notice">演示最高扣点10.0000，成功样例实际6.2500；均非供应商单价或系统默认值。真实计费条数和最高额度算法待验证。</div><pre>'+esc(JSON.stringify(snapshot,null,2))+'</pre><p>仅本页确认。可用 '+amount(S.balance-S.frozen)+' 点；锁定换算系数 '+S.query.coefficient+'。'+(title.includes('联系人')?'返回联系人不保证都有邮箱，字段缺失而可查看仍按实际费用结算。':'')+'</p><label>模拟返回场景<select id="queryScenario"><option value="success">可查看结果</option><option value="uncertain">请求超时，结果确认中</option><option value="zero">真实零结果</option><option value="failed">最终无法提供结果</option><option value="excess">可查看但实际超过确认上限</option></select></label><div class="actions"><button onclick="closeModal()">取消</button><button id="queryConfirm" class="primary" onclick="executeQuery()">确认本页最高10.0000点</button></div>');}
function executeQuery(){const q=S.query;if(!q||q.executed)return;const scenario=$('queryScenario').value;if(S.balance-S.frozen<q.max)return toast('可用余额不足以冻结，本次未发起查询');q.executed=true;S.frozen+=q.max;const params=q.title.includes('产品词')?{productDesc:q.snapshot.keyword,startDate:q.snapshot.start,endDate:q.snapshot.end,pageNo:q.snapshot.pageNo,pageSize:q.snapshot.pageSize,countryMapping:'UNVERIFIED — mock only',selectedBuyerCountry:q.snapshot.country}:q.title.includes('联系人')?{companyName:q.snapshot.companyName,positionTag:q.snapshot.positionTag,pageNo:q.snapshot.pageNo,pageSize:q.snapshot.pageSize}:{name:q.snapshot.name,countryCode3:q.snapshot.countryCode3};S.requests.push({queryId:q.id,kind:q.title,selection:{...q.snapshot},params,simulation:true});S.ledger.push({id:q.id,title:q.title,max:q.max,actual:null,refund:0,state:'结果确认中',frozen:q.max,coefficient:q.coefficient});S.pendingQueries=S.pendingQueries||{};S.pendingQueries[q.id]=q;closeModal();if(scenario==='uncertain'){toast('模拟请求超时：结果确认中，保留冻结，不自动重试');render();return}settleQuery(q.id,scenario);}
function settleQuery(id,scenario){const q=S.pendingQueries?.[id],entry=S.ledger.find(x=>x.id===id);if(!q||!entry)return;if(entry.state!=='结果确认中'){if(entry.state==='最终失败'&&scenario==='success'){entry.late=true;toast('迟到模拟结果已留存，不再次扣点');render()}return}const success=['success','excess'].includes(scenario),actual=success?Math.min(Number((6.25*q.coefficient).toFixed(4)),q.max):0;entry.actual=scenario==='excess'?q.max:actual;entry.state=success?'成功':scenario==='zero'?'零结果':'最终失败';entry.refund=entry.max-entry.actual;entry.frozen=0;S.frozen-=q.max;S.balance-=entry.actual;entry.excess=scenario==='excess';if(success)q.onSuccess();render();toast(success?'模拟结果可查看，已结算 '+amount(entry.actual)+' 点，释放剩余冻结':'本次'+entry.state+'，释放全部冻结；上游费用由平台承担');}
function archiveView(){const c=company();$('view').innerHTML=head('企业档案库','本企业全员共享；候选留在搜索结果。第三方数据仅在系统内查看。')+'<div class="panel"><div class="row between"><label>客户状态<select id="archiveFilter" onchange="filterArchives()"><option value="">全部</option>'+['线索','跟进中','已回复','无效'].map(x=>'<option>'+x+'</option>').join('')+'</select></label>'+(S.role==='admin'?'<label><input type="checkbox" id="showDeleted" onchange="filterArchives()"> 显示已软删除档案</label>':'')+'</div><div id="archiveRows"></div></div><div id="archiveDetail"></div>';filterArchives();if(c&&!c.deleted)detailView();}
function filterArchives(){const filter=$('archiveFilter')?.value,deleted=$('showDeleted')?.checked;const rows=S.archives.filter(c=>(deleted?c.deleted:!c.deleted)&&(!filter||c.status===filter));$('archiveRows').innerHTML='<table><thead><tr><th>企业</th><th>国家</th><th>客户状态</th><th>下次跟进</th><th>操作</th></tr></thead><tbody>'+rows.map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+esc(c.country)+'</td><td>'+esc(c.status)+'</td><td>'+esc(c.follow||'未设置')+'</td><td>'+(c.deleted?'<button onclick="restoreArchive(\''+c.id+'\')">恢复</button>':'<button onclick="openArchive(\''+c.id+'\')">查看档案</button>')+'</td></tr>').join('')+'</tbody></table>';}
function openArchive(id){S.companyId=id;S.selected={};S.archiveTab='概况';detailView()}
function detailView(){const c=company();if(!c||c.deleted)return;const tabs=['概况','联系人','统一时间线','附件'];$('archiveDetail').innerHTML='<section class="panel"><div class="row between"><div><h2>'+esc(c.name)+'</h2><span class="tag">'+c.country+'</span> <span class="tag">'+c.status+'</span></div><div class="row"><button onclick="updateCompany()">更新数据（确认费用）</button>'+(S.role==='admin'?'<button onclick="deleteArchive()">软删除档案</button>':'')+'</div></div><p class="hint">最近获取：'+esc(c.fetched)+'。本地再次查看免费，不因缓存到期自动付费更新。</p><div class="tabs">'+tabs.map(t=>'<button class="'+(t===S.archiveTab?'active':'')+'" onclick="archiveTab(\''+t+'\')">'+t+'</button>').join('')+'</div><div id="detailPane"></div></section>';if(S.archiveTab==='概况')overview();if(S.archiveTab==='联系人')peopleView();if(S.archiveTab==='统一时间线')timelineView();if(S.archiveTab==='附件')attachmentsView();}
function archiveTab(t){S.archiveTab=t;detailView()}
function updateCompany(){const c=company();requestQuery('主动更新企业详情',{name:c.name,countryCode3:c.country,pageNo:1,pageSize:1},()=>{c.fetched=S.date;toast('模拟更新完成，人工补充保留')})}
function deleteArchive(){if(S.role!=='admin')return;company().deleted=true;archiveView();toast('档案已模拟软删除，历史记录保留')}
function restoreArchive(id){if(S.role!=='admin')return;S.archives.find(c=>c.id===id).deleted=false;archiveView();toast('档案已恢复')}
function overview(){const c=company();$('detailPane').innerHTML='<div class="grid"><div><h3>腾道原始数据 · 模拟</h3><p>'+esc(c.name)+' · '+c.country+'</p><p>电话：暂无 · 官网：暂无</p><p class="hint">字段缺失而详情可查看，不按字段完整性退款。完整贸易分析第二阶段开放。</p></div><div><h3>人工补充</h3><div class="grid"><label>主营产品<input id="products" value="'+esc(c.products)+'"></label><label>采购需求<input id="needs" value="'+esc(c.needs)+'"></label><label>合作意向<input id="intent" value="'+esc(c.intent)+'"></label><label>下次跟进时间<input type="date" id="follow" value="'+esc(c.follow)+'"></label><label>客户状态<select id="customerStatus">'+['线索','跟进中','已回复','无效'].map(x=>'<option '+(c.status===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label></div><p class="hint">状态手动调整；下次跟进仅展示和筛选。修改留操作人和时间。</p><button class="primary" onclick="saveSupplement()">保存补充</button></div></div>';}
function saveSupplement(){const c=company();for(const k of ['products','needs','intent','follow'])c[k]=$(k).value;c.status=$('customerStatus').value;c.modifiedBy=currentActor();c.modifiedAt=S.date;filterArchives();toast('补充已保存（模拟），保留修改人和时间')}
function currentActor(){return S.role==='sales'?'业务员王敏':'企业管理员'}
function eligible(p){return p.company===company().name||!!S.ownership[p.mailsouId]}
function peopleView(){$('detailPane').innerHTML='<div class="row between"><h3>联系人</h3><div class="row"><select id="positionTag" style="width:150px" aria-label="职位筛选"><option value="">全部职位</option><option value="PURCHASING">采购</option><option value="EXECUTIVE">高管</option><option value="TECHNOLGY">技术研发</option></select><button onclick="queryContacts(1)">查询联系人（确认本页费用）</button><button onclick="queryContacts(2)">下一页（重新确认）</button></div></div><p class="hint">接口最多返回200条，触顶不代表实际人数；归属不一致先逐条确认。可信度不等于可投递性。</p><div class="tablewrap"><table><thead><tr><th>选择</th><th>姓名 / 来源企业</th><th>企业邮箱 / 个人邮箱</th><th>状态与操作</th></tr></thead><tbody>'+contacts.map(p=>{const selected=S.selected[p.mailsouId],ok=eligible(p);return '<tr><td><input aria-label="选择'+p.name+'" type="checkbox" '+(selected?'checked':'')+' '+(!ok?'disabled':'')+' onchange="selectContact(\''+p.mailsouId+'\',this.checked)"></td><td>'+p.name+'<br><span class="hint">'+esc(p.company)+'</span><br><span class="tag">'+p.confidence+'</span></td><td><label>本批收件地址<select aria-label="'+p.name+'收件地址" id="address-'+p.mailsouId+'" onchange="changeAddress(\''+p.mailsouId+'\',this.value)"><option value="">请选择地址</option>'+(p.email?'<option value="'+p.email+'" '+((selected?.address||p.email)===p.email?'selected':'')+'>企业：'+p.email+'</option>':'')+(p.personal?'<option value="'+p.personal+'" '+(selected?.address===p.personal?'selected':'')+'>个人：'+p.personal+'</option>':'')+'</select></label>'+(!p.email?'<span class="hint">企业邮箱缺失；个人邮箱须显式选择</span>':'')+'</td><td>'+(p.unsub?'<span class="tag warn">已退订 · 默认不选</span><br>':'')+(!ok?'<span class="tag warn">归属待核实</span><br><button class="small" onclick="confirmOwnership(\''+p.mailsouId+'\')">逐条确认归属</button>':S.ownership[p.mailsouId]?'<span class="tag good">人工确认归属</span>':'归属一致')+(p.missing?'<br>本次更新未返回（保留）':'')+'</td></tr>'}).join('')+'</tbody></table></div><div class="actions"><button class="primary" onclick="compose()">为所选联系人写邮件</button></div>';}
function queryContacts(page){const c=company(),position=$('positionTag').value;requestQuery('档案内联系人查询',{companyName:c.name,companyId:c.id,positionTag:position,pageNo:page,pageSize:10},()=>{if(page===2)contacts[0].missing=true;toast('模拟获取本页，旧联系人及历史记录保留')})}
function changeAddress(id,address){if(S.selected[id])S.selected[id].address=address}
function selectContact(id,checked){const p=contacts.find(p=>p.mailsouId===id);if(!checked){delete S.selected[id];return}if(!eligible(p))return toast('请先逐条确认归属');const address=$('address-'+id).value;if(!address){$('address-'+id).focus();$('detailPane').querySelector('input[aria-label="选择'+p.name+'"]').checked=false;return toast('请明确选择收件地址，不自动使用个人邮箱')}S.selected[id]={mailsouId:id,address};}
function confirmOwnership(id){openModal('逐条确认联系人归属','<p>原始来源企业：'+esc(contacts.find(p=>p.mailsouId===id).company)+'，目标档案：'+esc(company().name)+'</p><label>确认说明<textarea id="ownershipNote" placeholder="请说明核实依据"></textarea></label><div class="actions"><button class="primary" onclick="saveOwnership(\''+id+'\')">确认归属并保留说明</button></div>')}
function saveOwnership(id){const note=$('ownershipNote').value.trim();if(!note)return toast('必须填写归属确认说明');S.ownership[id]={note,actor:currentActor(),time:S.date};closeModal();peopleView();toast('人工确认已记录，原始企业归属保留')}
function compose(){if(!Object.keys(S.selected).length)return toast('请先在企业档案选择联系人与邮箱');draft={template:'intro',subject:TEMPLATES.intro.subject,body:TEMPLATES.intro.body,conflicts:{},previewed:false};drawComposer();}
function groupedRecipients(){const groups={};for(const selection of Object.values(S.selected)){const p=contacts.find(x=>x.mailsouId===selection.mailsouId);if(!eligible(p)||!selection.address)continue;(groups[selection.address]||(groups[selection.address]=[])).push(p)}return groups}
function drawComposer(){const grouped=groupedRecipients();openModal('写邮件 · 本次单轮','<p class="hint">从 '+esc(company().name)+' 档案发起；保存、预览或发送均不覆盖公共模板，也不扣查询点数。</p><div class="grid"><label>公共模板<select id="template" onchange="selectTemplate(this.value)">'+Object.entries(TEMPLATES).map(([k,t])=>'<option value="'+k+'" '+(draft.template===k?'selected':'')+'>'+t.name+'</option>').join('')+'</select></label><label>本批渠道<select id="sendChannel"><option value="smtp" '+(S.defaultChannel==='smtp'?'selected':'')+'>国内SMTP</option><option value="umail" '+(S.defaultChannel==='umail'?'selected':'')+'>U-Mail域名</option></select></label></div><label>本次主题<input id="subject" value="'+esc(draft.subject)+'"></label><label>本次内容<textarea id="body">'+esc(draft.body)+'</textarea></label><p class="hint">模板预设附件：'+TEMPLATES[draft.template].attachments.join('、')+'；发送时不提供临时附件上传。</p><h3>最终邮箱去重与变量来源</h3>'+Object.entries(grouped).map(([email,people])=>'<div class="item"><b>'+esc(email)+'</b> · '+people.length+'条联系人信息'+(people.length>1?'<label>同邮箱变量冲突，请明确选择<select class="conflict" data-email="'+esc(email)+'"><option value="">请选择称呼来源</option>'+people.map(p=>'<option value="'+p.mailsouId+'">'+p.name+' · '+p.mailsouId+'</option>').join('')+'</select></label>':' · '+people[0].name)+'</div>').join('')+(Object.values(S.selected).some(s=>contacts.find(p=>p.mailsouId===s.mailsouId).unsub)?'<div class="notice"><label><input type="checkbox" id="unsubConfirm"> 已选已退订地址。我已知晓退订标记，确认本次再次发送；上游限制仍有效。</label></div>':'')+'<div id="composeError" class="error"></div><div id="previews"></div><div class="actions"><button onclick="saveDraft()">保存本次草稿</button><button class="primary" onclick="previewMail()">预览</button></div>',true);}
function selectTemplate(k){draft.template=k;draft.subject=TEMPLATES[k].subject;draft.body=TEMPLATES[k].body;drawComposer()}
function saveDraft(){draft.subject=$('subject').value;draft.body=$('body').value;S.savedDraft={...draft};toast('已保存本次草稿（模拟），公共模板保持原内容')}
function renderVariables(text,p){return text.replace(/\{\{name\}\}/g,p.name).replace(/\{\{company\}\}/g,company().name)}
function validatedRecipients(){const grouped=groupedRecipients(),out=[];for(const [email,people] of Object.entries(grouped)){let p=people[0];if(people.length>1){const node=[...document.querySelectorAll('.conflict')].find(n=>n.dataset.email===email);const id=node?.value;if(!id)throw Error('同一邮箱有变量冲突，请人工选择联系人信息');p=people.find(x=>x.mailsouId===id)}const subject=renderVariables($('subject').value,p),body=renderVariables($('body').value,p);if(!subject.trim()||!body.trim()||/\{\{|\}\}/.test(subject+body))throw Error('模板变量缺失或未替换，请补全或修改本次内容');out.push({address:email,mailsouId:p.mailsouId,name:p.name,subject,body})}if(!out.length)throw Error('没有可发送的最终邮箱');return out}
function previewMail(){try{const recipients=validatedRecipients();if($('unsubConfirm')&&!$('unsubConfirm').checked)throw Error('请确认本次向已退订地址再次发送的提示');const q=quota();draft.previewed=true;draft.previewSnapshot={subject:$('subject').value,body:$('body').value,channel:$('sendChannel').value,recipients:JSON.stringify(recipients),unsub:$('unsubConfirm')?.checked||false};$('composeError').textContent='';$('previews').innerHTML='<h3>预览 · 去重后 '+recipients.length+' 个邮箱</h3>'+recipients.map(p=>'<div class="preview"><b>'+esc(p.address)+' · '+esc(p.subject)+'</b><p style="white-space:pre-wrap">'+esc(p.body)+'</p></div>').join('')+'<div class="notice">今日模拟额度 '+S.dailyLimit+'，已用 '+q.used+'，预占 '+q.reserved+'。本批确认时预占 '+recipients.length+'；两渠道共用，不扣点数。</div><label>模拟提交结果<select id="mailScenario"><option value="queued">保持排队（未提交）</option><option value="accepted">服务商受理</option><option value="failed">明确未提交成功</option><option value="uncertain">请求超时，结果待确认</option></select></label><div class="actions"><button class="primary" id="sendConfirm" onclick="sendMail()">确认本次单轮发送</button></div>';}catch(e){$('composeError').textContent=e.message;$('previews').innerHTML='';draft.previewed=false}}
function sendMail(){try{const recipients=validatedRecipients(),snap=draft.previewSnapshot;if(!draft.previewed||!snap||snap.subject!==$('subject').value||snap.body!==$('body').value||snap.channel!==$('sendChannel').value||snap.recipients!==JSON.stringify(recipients)||snap.unsub!==($('unsubConfirm')?.checked||false))throw Error('内容、渠道或收件人已变更，请重新预览');if($('unsubConfirm')&&!$('unsubConfirm').checked)throw Error('请确认退订提示');const channel=$('sendChannel').value;if(!S.channels[channel].ready)throw Error('所选渠道尚未完成配置验证');const q=quota();if(q.used+q.reserved+recipients.length>S.dailyLimit)throw Error('企业每日共享额度不足，不能通过切换渠道增加额度');const scenario=$('mailScenario').value;const batch={id:'batch-'+(S.batches.length+1),companyId:company().id,companyName:company().name,channel,actor:currentActor(),date:S.date,recipients,state:'排队中',reserved:recipients.length,used:0,submitted:false,events:[]};q.reserved+=recipients.length;S.batches.push(batch);if(scenario!=='queued')settleMail(batch.id,scenario,false);closeModal();S.selected={};S.page='邮件发送记录';render();toast('已创建模拟单轮批次；未连接邮箱服务');}catch(e){$('composeError').textContent=e.message}}
function settleMail(id,result,rerender=true){const b=S.batches.find(b=>b.id===id);if(!b||['已提交发信服务','已送达','发送失败'].includes(b.state))return;const q=quota(b.date);if(result==='accepted'){q.reserved-=b.reserved;q.used+=b.reserved;b.used+=b.reserved;b.reserved=0;b.submitted=true;b.state='已提交发信服务'}if(result==='failed'){q.reserved-=b.reserved;b.reserved=0;b.state='发送失败'}if(result==='uncertain'){b.submitted=true;b.state='结果待确认'}b.events.push({date:S.date,result});if(rerender)render()}
function mailView(){const q=quota();$('view').innerHTML=head('邮件发送记录','写邮件从企业档案联系人发起。以下状态均为模拟，受理成功不代表已送达或已回复。')+'<div class="panel"><div class="row between"><h2>企业今日额度</h2><span class="tag">两渠道、全团队共用</span></div><p>日期 '+S.date+'（北京时间） · 模拟上限 '+S.dailyLimit+' · 已用 '+q.used+' · 预占 '+q.reserved+' · 剩余 '+(S.dailyLimit-q.used-q.reserved)+'</p><p class="hint">北京时间零点重置，未用不累计；跨日未执行暂停重新确认。已提交不确定仍在原日期核对。</p></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>批次 / 档案</th><th>渠道 / 操作人</th><th>额度日期 / 邮箱数</th><th>状态</th><th>核对操作</th></tr></thead><tbody>'+S.batches.map(b=>'<tr><td>'+b.id+'<br>'+esc(b.companyName)+'</td><td>'+b.channel+'<br>'+b.actor+'</td><td>'+b.date+' / '+b.recipients.length+'<br>预占 '+b.reserved+' · 已用 '+b.used+'</td><td>'+b.state+'</td><td>'+(b.state==='排队中'?'<button class="small" onclick="settleMail(\''+b.id+'\',\'accepted\')">模拟受理</button> <button class="small" onclick="settleMail(\''+b.id+'\',\'uncertain\')">模拟超时</button>':b.state==='结果待确认'?'<button class="small" onclick="settleMail(\''+b.id+'\',\'accepted\')">核对为已受理</button> <button class="small" onclick="settleMail(\''+b.id+'\',\'failed\')">核对为未提交</button> <button class="small" onclick="uncertainResend(\''+b.id+'\')">仍不明，查看重发提示</button>':b.state==='跨日暂停'?'<button class="small" onclick="resumeBatch(\''+b.id+'\')">次日重新确认</button>':'只读记录')+'</td></tr>').join('')+'</tbody></table></div>'+(!S.batches.length?'<div class="empty">尚无发送记录。请从企业档案选择联系人写邮件。</div>':'')+'</div>'+testTools();}
function uncertainResend(id){openModal('结果仍待确认 · 可能重复发送','<div class="notice">原批次可能已经发出，原日期预占继续保留。再次发送可能重复，不能自动重发或绕过上游拒投。</div><p>可返回档案重新选择联系人、预览并确认新批次及当日额度。</p><div class="actions"><button onclick="closeModal()">继续核对</button><button onclick="resendViaArchive(\''+id+'\')">我决定重新选择并确认</button></div>')}
function resendViaArchive(id){const b=S.batches.find(b=>b.id===id);S.companyId=b.companyId;S.archiveTab='联系人';closeModal();go('企业档案库')}
function nextDay(){S.date='2026-10-'+(Number(S.date.slice(-2))+1);for(const b of S.batches){if(b.state==='排队中'&&b.date!==S.date){quota(b.date).reserved-=b.reserved;b.reserved=0;b.state='跨日暂停'}}render();toast('模拟北京时间跨日：未执行暂停并解除原日预占；已提交不确定保留原日核对')}
function resumeBatch(id){const b=S.batches.find(b=>b.id===id);if(b.state!=='跨日暂停')return;openModal('跨日重新确认','<p>旧批次未执行，原日预占已解除。本次将于 '+S.date+' 对 '+b.recipients.length+' 个邮箱重新预占。</p><div class="actions"><button class="primary" onclick="confirmResume(\''+id+'\')">确认占用新一天额度</button></div>')}
function confirmResume(id){const b=S.batches.find(b=>b.id===id),q=quota();if(b.state!=='跨日暂停')return;if(q.used+q.reserved+b.recipients.length>S.dailyLimit)return toast('新一天共享额度不足');b.previousDates=b.previousDates||[];b.previousDates.push(b.date);b.date=S.date;b.reserved=b.recipients.length;b.state='排队中';q.reserved+=b.reserved;closeModal();render()}
function timelineView(){const c=company();$('detailPane').innerHTML='<div class="row between"><h3>统一时间线</h3><div class="row"><select id="timelineFilter" aria-label="时间线类型筛选" onchange="timelineRows()" style="width:150px"><option value="">全部类型</option><option>邮件</option><option>回复摘要</option><option>备注</option><option>WhatsApp</option></select><button onclick="recordModal()">新增人工记录</button></div></div><div id="timelineRows" class="timeline"></div>';timelineRows();}
function timelineRows(){const c=company(),filter=$('timelineFilter')?.value;const manual=c.records.filter(r=>!r.deleted).map(r=>({...r,system:false})),mail=S.batches.filter(b=>b.companyId===c.id).map(b=>({id:b.id,type:'邮件',time:b.date+' 12:00',content:b.recipients.length+'个邮箱 · '+b.state,actor:b.actor,system:true}));const rows=[...manual,...mail].filter(r=>!filter||r.type===filter).sort((a,b)=>b.time.localeCompare(a.time));$('timelineRows').innerHTML=rows.map(r=>'<article class="item"><div class="itemhead"><div><span class="tag">'+r.type+'</span> '+esc(r.time)+' · '+esc(r.actor)+'</div><div>'+(r.system?'<span class="hint">系统记录不可手改删</span>':(r.actor===currentActor()?'<button class="small" onclick="recordModal(\''+r.id+'\')">编辑</button> ':'')+(S.role==='admin'?'<button class="small" onclick="deleteRecord(\''+r.id+'\')">软删除</button>':''))+'</div></div><p>'+esc(r.content)+'</p>'+(r.contact?'<p class="hint">联系人或号码：'+esc(r.contact.replace(/(\d{3})\d+(\d{4})/,'$1****$2'))+'</p>':'')+'</article>').join('')||'<div class="empty">暂无记录。回复摘要和WhatsApp均由业务员手动登记。</div>';}
function recordModal(id){const r=company().records.find(r=>r.id===id);if(r&&r.actor!==currentActor())return toast('只能编辑自己创建的人工记录');S.editRecord=id;openModal(r?'编辑人工记录':'新增人工记录','<div class="grid"><label>类型<select id="recordType">'+['备注','回复摘要','WhatsApp'].map(t=>'<option '+(r?.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>沟通时间<input id="recordTime" type="datetime-local" value="'+(r?.time.replace(' ','T')||S.date+'T10:00')+'"></label></div><label>联系人或号码<input id="recordContact" value="'+esc(r?.contact||'')+'"></label><label>内容摘要<textarea id="recordContent">'+esc(r?.content||'')+'</textarea></label><label>附件（模拟留档，不上传网络）<input id="recordFiles" type="file" multiple accept=".jpg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.zip,.rar"></label><p class="hint">WhatsApp只有时间、联系人或号码、摘要、附件；下次跟进在档案统一字段。人工记录创建人编辑，管理员软删除。</p><div class="actions"><button class="primary" onclick="saveRecord()">保存记录</button></div>')}
function saveRecord(){const c=company(),type=$('recordType').value,time=$('recordTime').value.replace('T',' '),contact=$('recordContact').value.trim(),content=$('recordContent').value.trim();if(!time||!content||(type==='WhatsApp'&&!contact))return toast('请填写沟通时间和内容摘要；WhatsApp需联系人或号码');if(time.slice(0,10)>S.date)return toast('沟通时间不能晚于当前模拟日期');const existing=c.records.find(r=>r.id===S.editRecord);if(existing&&existing.actor!==currentActor())return;const id=existing?.id||'record-'+(++S.recordSerial);const files=[...$('recordFiles').files];if(!validateFiles(files))return;files.forEach(f=>addAttachment(f,id));if(existing)Object.assign(existing,{type,time,contact,content,modifiedAt:S.date});else c.records.push({id,type,time,contact,content,actor:currentActor(),createdAt:S.date});closeModal();timelineView();toast('模拟人工记录已保存；客户状态仍由业务员手动调整')}
function deleteRecord(id){if(S.role!=='admin')return;const r=company().records.find(r=>r.id===id);r.deleted=true;r.deletedBy=currentActor();r.deletedAt=S.date;timelineRows()}
function validateFiles(files){if(company().attachments.filter(a=>!a.deleted).length+files.length>50){toast('单企业附件上限50');return false}if(files.some(f=>f.size>20*1024*1024||!/[.](jpg|png|webp|pdf|doc|docx|xls|xlsx|ppt|pptx|zip|rar)$/i.test(f.name))){toast('附件格式不在白名单或超过20MB；服务端MIME校验仍待实现');return false}return true}
function addAttachment(file,recordId=null){company().attachments.push({id:'attachment-'+(company().attachments.length+1),name:file.name,size:file.size,file,recordId,actor:currentActor(),deleted:false})}
function attachmentsView(){$('detailPane').innerHTML='<h3>档案附件</h3><p class="hint">仅上传、下载和企业管理员软删除。演示仅保存在本页内存，生产仍须服务端MIME与私有访问校验。附件不自动成为邮件附件。</p><label>上传资料<input type="file" id="archiveFile" multiple accept=".jpg,.png,.webp,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.zip,.rar" onchange="uploadFiles(this.files)"></label>'+company().attachments.filter(a=>!a.deleted).map(a=>'<div class="item row between"><span>'+esc(a.name)+' · '+a.size+' bytes</span><div class="row"><button class="small" onclick="downloadAttachment(\''+a.id+'\')">下载</button>'+(S.role==='admin'?'<button class="small" onclick="deleteAttachment(\''+a.id+'\')">软删除</button>':'')+'</div></div>').join('');}
function uploadFiles(files){if(!validateFiles([...files]))return;[...files].forEach(f=>addAttachment(f));attachmentsView();toast('附件已模拟留档，仅在本页内存中')}
function downloadAttachment(id){const a=company().attachments.find(a=>a.id===id&&!a.deleted);if(!a?.file)return;const url=URL.createObjectURL(a.file),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);a.lastDownloadedBy=currentActor();toast('下载当前用户上传的本地演示附件，已记录操作')}
function deleteAttachment(id){if(S.role!=='admin')return;const a=company().attachments.find(a=>a.id===id);a.deleted=true;a.deletedBy=currentActor();a.deletedAt=S.date;attachmentsView()}
function settingsView(){if(S.role!=='admin')return;$('view').innerHTML=head('团队发信设置','每企业国内SMTP、U-Mail域名渠道各一套；团队共用，按批选择一种。')+'<div class="notice">平台统一采购并承担第一阶段U-Mail费，按企业隔离。域名验证、真实回复收信、渠道状态回收均需联调；本页仅模拟配置。</div><div class="grid">'+['smtp','umail'].map(k=>'<section class="panel"><h2>'+(k==='smtp'?'国内邮箱SMTP':'U-Mail域名发信')+'</h2><p class="tag good">模拟配置已就绪</p><label>发信地址<input id="sender-'+k+'" value="'+esc(S.channels[k].sender)+'"></label><label>真实可收信的团队回复地址<input id="reply-'+k+'" value="'+esc(S.channels[k].reply)+'"></label><p class="hint">'+(k==='smtp'?'生产需SMTP服务、端口、加密与授权凭据；凭据只在服务端保存。':'域名DNS以供应商实际记录为准；平台完成隔离资源配置，终端企业配合验证。')+'</p><button onclick="saveChannel(\''+k+'\')">保存本套配置</button> <button onclick="toast(\'模拟连通状态通过，未进行真实测试发信\')">模拟验证</button></section>').join('')+'</div><div class="panel"><label>默认渠道<select onchange="S.defaultChannel=this.value"><option value="smtp" '+(S.defaultChannel==='smtp'?'selected':'')+'>国内SMTP</option><option value="umail" '+(S.defaultChannel==='umail'?'selected':'')+'>U-Mail域名</option></select></label><p>两渠道每日额度共用，当前模拟日上限 '+S.dailyLimit+'。无自动收信，客户回复在原邮箱查看并人工登记。</p></div>';}
function saveChannel(k){const sender=$('sender-'+k).value.trim(),reply=$('reply-'+k).value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(sender)||!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(reply))return toast('请填写有效发信地址和可收信回复地址');S.channels[k]={sender,reply,ready:true};toast('模拟配置已保存，每渠道仍仅一套')}
function membersView(){if(S.role!=='admin')return;$('view').innerHTML=head('成员管理','直接创建账号，可重置密码或停用。停用后保留其档案和历史记录。')+'<div class="panel"><button class="primary" onclick="memberModal()">创建成员</button><table><thead><tr><th>成员</th><th>登录账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>'+S.members.map(m=>'<tr><td>'+esc(m.name)+'</td><td>'+esc(m.login)+'</td><td>'+m.role+'</td><td>'+(m.active?'启用':'停用')+'</td><td><button class="small" onclick="resetMember('+m.id+')">重置密码</button> <button class="small" onclick="toggleMember('+m.id+')">'+(m.active?'停用':'恢复')+'</button></td></tr>').join('')+'</tbody></table></div>';}
function memberModal(){openModal('直接创建成员','<div class="grid"><label>姓名<input id="memberName"></label><label>登录邮箱<input id="memberLogin" type="email"></label><label>初始密码<input id="memberPassword" type="password"></label><label>角色<select id="memberRole"><option>业务员</option><option>终端企业管理员</option></select></label></div><div class="actions"><button class="primary" onclick="createMember()">创建本企业成员</button></div>')}
function createMember(){const name=$('memberName').value.trim(),login=$('memberLogin').value.trim();if(!name||!login||!$('memberPassword').value)return toast('请填写姓名、登录邮箱和初始密码');if(S.members.some(m=>m.login===login))return toast('账号已存在');S.members.push({id:++S.memberSerial,name,login,role:$('memberRole').value,active:true});closeModal();membersView();toast('已模拟创建本企业成员，无邀请邮件')}
function resetMember(id){openModal('重置成员密码','<label>新密码<input id="newPassword" type="password"></label><div class="actions"><button class="primary" onclick="savePassword('+id+')">保存新密码</button></div>')}
function savePassword(id){if(!$('newPassword').value)return toast('请填写新密码');S.members.find(m=>m.id===id).passwordResetAt=S.date;closeModal();toast('密码已模拟重置，不在原型中保存密码明文')}
function toggleMember(id){const m=S.members.find(m=>m.id===id);m.active=!m.active;membersView();toast('成员状态已变更，档案与历史记录保留')}
function pointsView(){$('view').innerHTML=head('点数用量','本企业余额、冻结点数和查询扣点流水；内部点数不设有效期。')+'<div class="panel grid three"><div>总余额<div class="balance">'+amount(S.balance)+'</div></div><div>查询冻结<div class="balance">'+amount(S.frozen)+'</div></div><div>可用余额<div class="balance">'+amount(S.balance-S.frozen)+'</div></div></div><div class="panel"><h2>查询扣点流水</h2><div class="tablewrap"><table><thead><tr><th>查询</th><th>预估最高额度</th><th>实际扣点</th><th>释放 / 退款</th><th>状态与核对</th></tr></thead><tbody>'+S.ledger.map(l=>'<tr><td>'+l.id+' · '+esc(l.title)+'</td><td>'+amount(l.max)+'</td><td>'+(l.actual===null?'待确认':amount(l.actual))+'</td><td>'+amount(l.refund)+'</td><td>'+l.state+(l.excess?' · 超额平台承担':'')+(l.late?' · 迟到结果不重扣':'')+(l.state==='结果确认中'?'<br><span class="hint">平台人工核对：依据、操作人和时间留痕；无未经验证的固定期限</span>':'')+'</td></tr>').join('')+'</tbody></table></div></div>'+testTools();}
function childrenView(){$('view').innerHTML=head('下级管理','仅直属上级可开户和定价。最多两级分销，组织上级不可迁移。')+'<section class="panel"><p>'+ (S.role==='platform'?'平台 → 一级分销（直属） → 二级分销 → 终端企业；平台可看全链，不可跨级交易。':'当前：二级分销（演示） → 终端企业（直属）；本级不可再建分销节点。')+'</p><p>可查看下级开户、余额、交易与汇总用量，无法查看其查询关键词、目标企业、联系人和邮件。</p><button onclick="childModal()">开户（直属下级）</button><h3 style="margin-top:25px">演示终端企业</h3><p>组织启用 · 余额 '+amount(S.supplier.buyerBalance)+' · 直属上级：当前组织</p><label>每点售价（模拟）<input id="salePrice" type="number" value="0.20" step="0.01"></label><p class="hint">模拟平均进价0.15，m=10%，最低售价0.165；均为测试值，不是实际商务配置。</p><button onclick="savePrice()">保存售价</button></section>';}
function childModal(){openModal('直属开户 · 演示','<label>组织名称<input id="childName"></label><label>组织类型<select id="childKind"><option value="terminal">终端企业</option>'+(S.role==='platform'?'<option value="distributor">一级分销</option>':'')+'</select></label><p class="hint">开户即固定直属上级；本页不提供迁移功能。</p><div class="actions"><button onclick="if(!$(\'childName\').value.trim())return toast(\'请填名称\');S.newChild={name:$(\'childName\').value,kind:$(\'childKind\').value};closeModal();toast(\'模拟直属开户完成\')">确认开户</button></div>')}
function savePrice(){const p=Number($('salePrice').value);if(p<S.supplier.averageCost*(1+S.supplier.m))return toast('低于当前成本与最低加价率下限，阻止保存；请重新定价');S.supplier.price=p;toast('模拟售价保存，m不是净利润保障')}
function ordersView(){const a=S.supplier,o=a.order;$('view').innerHTML=head('点数订单','一单一笔足额线下收款，一次完整划拨。收款确认时预留库存。')+'<section class="panel"><p>卖方余额 '+amount(a.balance)+' · 销售预留 '+amount(a.salesReserved)+' · 可分配 '+amount(a.balance-a.salesReserved)+' · 下级余额 '+amount(a.buyerBalance)+'</p>'+(!o?'<div class="grid"><label>购买点数<input id="orderQuantity" value="100" type="number"></label><label>每点售价（模拟）<input id="orderPrice" value="0.20" type="number" step="0.01"></label></div><button class="primary" style="margin-top:15px" onclick="createOrder()">创建点数订单</button>':'<h2>订单 order-demo-01 · '+o.state+'</h2><p>'+amount(o.quantity)+' 点 × '+o.price+' = '+o.amount+' 元（模拟）</p><p>数量和售价'+(o.state==='待收款'?'将在确认收款时锁定':'已锁定，不因新成本或m改变')+'</p><div class="row">'+(o.state==='待收款'?'<button class="primary" onclick="confirmReceipt()">确认足额线下收款并预留</button>':o.state==='已收款待划拨'?'<button class="primary" onclick="transfer()">完整划拨</button><button onclick="refundModal()">整单退款</button><label><input type="checkbox" onchange="S.supplier.disabled=this.checked;toast(this.checked?\'组织停用：暂停划拨保留销售预留\':\'组织恢复\')"> 模拟相关组织停用</label>':'<span class="hint">已完成状态不可重复划拨；已划拨第一阶段不支持退回退款。</span>')+'</div>')+'</section>'+testTools();}
function createOrder(){const quantity=Number($('orderQuantity').value),price=Number($('orderPrice').value),a=S.supplier;if(!(quantity>0)||!Number.isFinite(price)||price<a.averageCost*(1+a.m))return toast('数量必须有效且售价须达到最新成本与m下限');a.order={quantity,price,amount:Number((quantity*price).toFixed(2)),state:'待收款'};ordersView()}
function confirmReceipt(){const a=S.supplier,o=a.order;if(o?.state!=='待收款')return;if(a.disabled)return toast('组织停用，不能进行新交易');if(o.price<a.averageCost*(1+a.m))return toast('新成本或m变化，旧售价不足，阻止成交并要求上级重新定价');if(a.balance-a.salesReserved<o.quantity)return toast('库存不足，不能完成系统收款确认；线下款项可能已到账，请处理补库存或退款，具体流程待确认');a.salesReserved+=o.quantity;o.state='已收款待划拨';o.costSnapshot=a.averageCost;o.receipt='receipt-demo-unique';ordersView()}
function transfer(){const a=S.supplier,o=a.order;if(o?.state!=='已收款待划拨')return toast('订单状态不允许重复划拨');if(a.disabled)return toast('相关组织停用，暂停划拨且保留销售预留');a.balance-=o.quantity;a.salesReserved-=o.quantity;a.buyerBalance+=o.quantity;o.state='已划拨';ordersView();toast('内部上减下加，未调用腾道，未改变上游余额')}
function refundModal(){openModal('整单退款','<p>仅已收款尚未划拨订单支持。卖方需确认线下退款已经完成，才关闭订单并释放销售预留。</p><label><input type="checkbox" id="refundDone"> 我已完成整笔线下退款</label><div class="actions"><button onclick="confirmRefund()">确认退款并关闭</button></div>')}
function confirmRefund(){const a=S.supplier,o=a.order;if(!$('refundDone').checked)return toast('请先确认线下整单退款已完成');if(o?.state!=='已收款待划拨')return;a.salesReserved-=o.quantity;o.state='已退款关闭';o.refundActor=currentActor();o.refundDate=S.date;closeModal();ordersView()}
function profitsView(){const o=S.supplier.order;$('view').innerHTML=head('交易与利润','仅展示账务及汇总用量。历史交易成本与毛利不因后续采购重算。')+'<section class="panel"><h2>交易明细 · 模拟</h2>'+(o?'<p>order-demo-01 · '+o.state+' · '+o.quantity+' 点 · 售价 '+o.price+'</p><p>锁定成本 '+(o.costSnapshot??'待收款确认')+'；'+(o.state==='已划拨'?'销售毛利 '+((o.price-o.costSnapshot)*o.quantity).toFixed(2)+' 元':'未完成销售，不展示已实现毛利')+'</p>':'<p class="muted">暂无订单</p>')+'<p>不含下级查询关键词、目标企业、联系人或邮件内容。</p><button onclick="downloadAccounting()">导出自有账务对账单（模拟）</button></section>';}
function downloadAccounting(){const o=S.supplier.order,body='订单,状态,点数,单价\n'+(o?['order-demo-01',o.state,o.quantity,o.price].join(','):'暂无');const url=URL.createObjectURL(new Blob(['\ufeff'+body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='模拟自有账务.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('仅导出自有账务，无下级业务或腾道数据')}
function platformView(){$('view').innerHTML=head('平台配置','上游单价、查询系数与内部定价分别管理。演示配置不能作为上线默认值。')+'<section class="panel"><label><input type="checkbox" id="priceConfigured" '+(S.priceConfigured?'checked':'')+' onchange="S.priceConfigured=this.checked"> 模拟接口单价已配置（取消后阻止计费查询）</label><div class="grid"><label>统一换算系数X（演示）<input type="number" id="coefficient" value="'+S.coefficient+'" min="0.0001" step="0.1"></label><label>上游余额是否覆盖（演示）<select id="coverage"><option value="no">未验证或不足</option><option value="yes">模拟覆盖核对已通过</option></select></label></div><p class="hint">X默认1；新系数不改已有余额，旧确认锁旧系数。降低前核对全链未耗点数含销售预留、查询冻结且去重，区分在途已扣费；不足先补上游，补缺口不增发内部点数。</p><button onclick="saveCoefficient()">确认演示系数变更</button><p id="coefficientResult"></p></section><section class="panel"><h2>待验证的真实参数</h2><p>各接口商务单价、m、账号覆盖、报价算法、精度及账单延迟；U-Mail隔离与结果回收。通知仅系统内，不启用短信或邮件告警。</p></section>';}
function saveCoefficient(){const x=Number($('coefficient').value);if(!(x>0))return toast('请输入正系数');if(x<S.coefficient&&$('coverage').value!=='yes')return toast('降低系数前覆盖未核对通过，不允许生效');S.coefficient=x;$('coefficientResult').textContent='模拟新系数已生效；已有余额不改，待确认查询沿原锁定系数核对。';}
function businessView(){$('view').innerHTML=head('平台业务数据查看','平台运营默认可查看档案及邮件内容，此处为只读例外。')+'<section class="panel"><h2>'+esc(company().name)+'</h2><p>客户状态：'+company().status+' · '+company().country+'</p>'+S.batches.map(b=>'<div class="item">'+b.id+' · '+b.state+b.recipients.map(p=>'<p>'+esc(p.subject)+'<br>'+esc(p.body)+'</p>').join('')+'</div>').join('')+'<p class="hint">查看不赋予跨企业修改、删除、发信或导出腾道数据权限。</p></section>';}
function testTools(){return '<details class="panel"><summary>模拟状态验证工具（不连接真实服务）</summary><p class="hint">可模拟跨日与核对结果；所有费用、额度、身份和供应商结果仅为演示。</p><button class="small" onclick="nextDay()">模拟北京时间次日零点</button> <button class="small" onclick="inspectRequests()">查看选择与提交快照</button> <button class="small" onclick="openReconciliation()">模拟平台人工核对</button></details>';}
function inspectRequests(){openModal('模拟选择与提交快照','<p class="hint">接口契约尚未真实联调；产品词国家映射明确标记未验证，不自动写目的国。列表ID、详情ID、mailsouId与fileId演示值刻意不同。</p><pre>'+esc(JSON.stringify(S.requests,null,2))+'</pre>',true)}
function openReconciliation(){openModal('模拟平台人工核对','<p>真实系统仅平台操作；需保存依据、操作人和时间，不能扩大为跨级销售权。</p>'+S.ledger.map(l=>'<div class="item">'+l.id+' · '+l.state+' <button onclick="settleQuery(\''+l.id+'\',\'success\');closeModal()">模拟确认可查看</button> <button onclick="settleQuery(\''+l.id+'\',\'failed\');closeModal()">模拟最终失败</button></div>').join(''))}
window.prototypeState=S;window.prototypeContracts={contacts,templates:TEMPLATES};render();
</script></body></html>'''
(root/'原型设计/prototype-smart-acquisition.html').write_text(html,encoding='utf-8')
print('prototype saved')
